def load_constraint_spec(constraints_path):
    """Load ontology constraints, normalizing DocRED P-codes to relation names."""
    with open(constraints_path) as f:
        raw = json.load(f)

    entity_types = raw["entity_types"]
    raw_rtypes = raw.get("relation_types", [])

    if isinstance(raw_rtypes, dict):
        # DocRED: {P-code: name} dict -> use names as relation types
        code_to_name = raw_rtypes
        relation_types = list(code_to_name.values())
        relation_constraints = {}
        for code, data in raw.get("relation_constraints", {}).items():
            name = code_to_name.get(code, code)
            relation_constraints[name] = RelationConstraint(
                relation_type=name,
                valid_pairs=[(h, t) for h, t in data["valid_pairs"]],
            )
    else:
        # SciERC: plain list
        relation_types = raw_rtypes
        relation_constraints = {}
        for rtype, data in raw.get("relation_constraints", {}).items():
            relation_constraints[rtype] = RelationConstraint(
                relation_type=rtype,
                valid_pairs=[(h, t) for h, t in data["valid_pairs"]],
            )

    # EE fields
    event_types = raw.get("event_types", [])
    argument_constraints = raw.get("argument_constraints", {})
    if not argument_constraints and "event_constraints" in raw:
        raw_ec = raw["event_constraints"]
        argument_constraints = {}
        for evt_type, evt_data in raw_ec.items():
            argument_constraints[evt_type] = evt_data.get("role_entity_constraints", {})

    all_roles_set = set()
    for evt_constraints in argument_constraints.values():
        all_roles_set.update(evt_constraints.keys())
    all_roles = sorted(all_roles_set)

    return ConstraintSpec(
        entity_types=entity_types,
        relation_types=relation_types,
        relation_constraints=relation_constraints,
        event_types=event_types,
        all_roles=all_roles,
        argument_constraints=argument_constraints,
    )


